    exports2.deleteTask = async (req, res) => {
      const pool = req.app.locals.db;
      const { id: taskId } = req.params;
      const { userId, isAdmin } = req.body;
      const taskIdInt = parseInt(taskId, 10);
      if (!userId) {
        return res.status(401).json({ message: "User identification is required." });
      }
      if (isNaN(taskIdInt)) {
        return res.status(400).json({ message: "Invalid task ID" });
      }
      const transaction = new sql2.Transaction(pool);
      try {
        await transaction.begin();
        const accessCheck = await checkTaskAccess(pool, taskIdInt, userId, isAdmin === "true", "delete");
        if (!accessCheck.hasAccess) {
          await transaction.rollback();
          return res.status(403).json({ message: accessCheck.reason });
        }
        const taskMetaRes = await new sql2.Request(transaction).input("TaskID", sql2.Int, taskIdInt).query("SELECT TOP 1 Title, DepartmentID FROM dbo.Tasks WHERE TaskID = @TaskID");
        const taskMeta = taskMetaRes.recordset[0] || {};
        await new sql2.Request(transaction).input("TaskID", sql2.Int, taskIdInt).query("DELETE FROM Comments WHERE TaskID = @TaskID");
        await new sql2.Request(transaction).input("TaskID", sql2.Int, taskIdInt).query("DELETE FROM Subtasks WHERE TaskID = @TaskID");
        await new sql2.Request(transaction).input("TaskID", sql2.Int, taskIdInt).query(`IF OBJECT_ID('dbo.TaskRelations','U') IS NOT NULL
                DELETE FROM dbo.TaskRelations WHERE TaskID1 = @TaskID OR TaskID2 = @TaskID`);
        await new sql2.Request(transaction).input("TaskID", sql2.Int, taskIdInt).query("DELETE FROM Tasks WHERE TaskID = @TaskID");
        await transaction.commit();
        await logTaskAction(pool, {
          taskId: taskIdInt,
          taskTitle: taskMeta.Title || null,
          departmentId: taskMeta.DepartmentID || null,
          action: "deleted",
          userId
        });
        res.status(200).json({ message: "Task and all related data deleted successfully" });
      } catch (error) {
        await transaction.rollback();
        console.error("DATABASE DELETE TASK ERROR:", error);
        res.status(500).send({ message: "Error deleting task" });
      }
    };
