          await new sql2.Request(transaction).input("SRC", sql2.Int, vacancyId).input("TGT", sql2.Int, targetId).query(`UPDATE dbo.Tasks SET AssignedToVacancyID = @TGT WHERE AssignedToVacancyID = @SRC`);
